cd /workspace/task && python3 - <<'EOF'
import openpyxl
wb = openpyxl.load_workbook('init.xlsx')
c = wb['combined']
print("=== combined rows ===")
for r in range(1,4):
    for col in range(1,19):
        cell = c.cell(r,col)
        if cell.value is not None:
            print(r, openpyxl.utils.get_column_letter(col), repr(cell.value), 'fmt=', cell.number_format)
print("=== combined number formats all I:R ===")
for r in range(1,4):
    for col in range(9,19):
        cell=c.cell(r,col)
        print(r, openpyxl.utils.get_column_letter(col), repr(cell.number_format))
EOF
